create extension if not exists pgcrypto;
create type public.autocall_role as enum ('platform_admin','company_admin','team_lead','employee');
create table public.companies(id uuid primary key default gen_random_uuid(),name text not null,status text not null default 'ACTIVE',created_at timestamptz not null default now());
create table public.autocall_profiles(id uuid primary key references auth.users(id) on delete cascade,company_id uuid references public.companies(id),role public.autocall_role not null default 'employee',display_name text,active boolean not null default true,created_at timestamptz not null default now());
create table public.teams(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),name text not null,created_at timestamptz not null default now(),unique(company_id,name));
create table public.employees(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),user_id uuid unique references auth.users(id),team_id uuid references public.teams(id),name text not null,status text not null default 'ACTIVE',created_at timestamptz not null default now());
create table public.leads(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),customer_name text,phone_e164 text not null,source text,campaign_name text,product_interest text,region text,memo text,status text not null default 'NEW',current_assignee_id uuid references public.employees(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.consent_pool(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),lead_id uuid not null unique references public.leads(id),consented_at timestamptz not null,priority_score int not null default 0,current_assignee_id uuid references public.employees(id),created_at timestamptz not null default now());
create table public.assignments(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),lead_id uuid not null references public.leads(id),employee_id uuid not null references public.employees(id),assigned_by uuid not null references auth.users(id),assigned_at timestamptz not null default now(),revoked_at timestamptz,revoke_reason text);
create table public.assignment_history(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),lead_id uuid not null references public.leads(id),from_employee_id uuid references public.employees(id),to_employee_id uuid references public.employees(id),action text not null,actor_user_id uuid not null references auth.users(id),reason text,created_at timestamptz not null default now());
create table public.counseling_logs(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),lead_id uuid not null references public.leads(id),employee_id uuid not null references public.employees(id),status text not null,memo text,callback_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),company_id uuid references public.companies(id),user_id uuid references auth.users(id),action text not null,target_type text,target_id uuid,before_data jsonb,after_data jsonb,created_at timestamptz not null default now());
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;
create or replace function private.current_company_id() returns uuid language sql stable security definer set search_path='' as $$ select company_id from public.autocall_profiles where id=(select auth.uid()) and active=true limit 1 $$;
create or replace function private.current_autocall_role() returns text language sql stable security definer set search_path='' as $$ select role::text from public.autocall_profiles where id=(select auth.uid()) and active=true limit 1 $$;
revoke all on function private.current_company_id() from public; revoke all on function private.current_autocall_role() from public;
grant execute on function private.current_company_id() to authenticated; grant execute on function private.current_autocall_role() to authenticated;
alter table public.companies enable row level security; alter table public.autocall_profiles enable row level security; alter table public.teams enable row level security; alter table public.employees enable row level security; alter table public.leads enable row level security; alter table public.consent_pool enable row level security; alter table public.assignments enable row level security; alter table public.assignment_history enable row level security; alter table public.counseling_logs enable row level security; alter table public.audit_logs enable row level security;
create policy companies_tenant_read on public.companies for select to authenticated using(id=private.current_company_id() or private.current_autocall_role()='platform_admin');
create policy profiles_tenant_read on public.autocall_profiles for select to authenticated using(company_id=private.current_company_id() or id=(select auth.uid()) or private.current_autocall_role()='platform_admin');
create policy employees_tenant_read on public.employees for select to authenticated using(company_id=private.current_company_id());
create policy leads_tenant_read on public.leads for select to authenticated using(company_id=private.current_company_id());
create policy pool_admin_read on public.consent_pool for select to authenticated using(company_id=private.current_company_id() and private.current_autocall_role() in('company_admin','team_lead'));
create policy assignments_tenant_read on public.assignments for select to authenticated using(company_id=private.current_company_id());
create index idx_leads_company_status on public.leads(company_id,status);
create index idx_pool_company_time on public.consent_pool(company_id,consented_at desc);
